function BsubDockHTML(selected,incoming){const off=selected&&incoming&&slotPenalty(incoming,selected.e.slot)>0;
  return `<div class="bdock bsub-dock" id="bsub-confirm"><div class="bsub-sum"><span class="out"><i>${selected?'יוצא':'במקום'}</i><b>${selected?esc(fullName(selected.p)):'השחקן שנפצע'}</b></span><span class="in${incoming?'':' todo'}"><i>נכנס</i><b>${incoming?esc(fullName(incoming)):'בחר מהספסל'}</b></span>${off?'<small>לא בעמדה הטבעית שלו</small>':''}</div>${Bbutton('אישור חילוף',`data-blive="sub-confirm"${incoming?'':' disabled'}`)}</div>`}
function BconfirmSub(){const live=Bstate().live;if(!live||BsubOut===undefined||BsubIn===undefined)return false;const M=live.M;if(BsubOut===0&&!BcanFillInjury(M))return false;if(!doSub(M,me(),BsubOut||null,BsubIn))return false;M.tadjDirty=true;live.paused=true;BsubOut=undefined;BsubIn=undefined;Bwrite();document.querySelector('.bdialog')?.remove();B3d?.update();if(Bpitch)pitchMinute(Bpitch,M,club(M.h),club(M.a),M.ev.filter(e=>e.m===M.m));BpaintBroadcast();return true}
/* 'hl' = highlights: quiet minutes fly by, a minute with a key event is held long enough to see it (about 40 s a match) */
let BhlUntil=0,BshoutPaint=null;
function BstartClock(){clearInterval(BmatchTimer);const sp=Bstate().live?.speed||1;BmatchTimer=setInterval(()=>Btick(),sp==='hl'?230:1000/sp)}
/* A penalty for or against the manager's club in a watched match is his to take: the clock waits while the overlay of the
   full game runs (he kicks for his side, keeps goal against it) and the engine is told how it ended. */
let BpenBusy=false;const BpenUI={pen:()=>G.penGame!==false&&!BpenBusy};
function BpenTake(M){const pp=M.pendingPen,c=club(pp.team),taker=c&&c.players.find(p=>p.id===pp.pid);if(!taker)return;BpenBusy=true;
  penMatchKick(M,c,taker,(out,how)=>{if(M.pendingPen===pp){M.pendingPen=null;penResolve(M,c,taker,out,how)}if(G?.beginner?.live?.M===M){BpaintBroadcast();Bwrite()}setTimeout(()=>{BpenBusy=false},penQuick()?0:700)})}
function Btick(force=false){const live=G?.beginner?.live;if(!live||(!force&&(document.hidden||live.paused||BpenBusy||B3d?.busy||(!B3d?.enabled&&Bpitch?.hold)||(live.speed==='hl'&&performance.now()<BhlUntil))))return;const M=live.M;if(!M.done){B3d?.beforeStep();const ev0=M.ev.length;stepMinute(M,force?undefined:BpenUI);if(M.pendingPen&&!force){BpaintBroadcast();return BpenTake(M)}M.voice=Math.min(100,(M.voice==null?60:M.voice)+100/12);if(BshoutPaint)BshoutPaint();if(live.speed==='hl'&&!force){const ms=hlHoldMs(M.ev.slice(ev0));BhlUntil=ms?performance.now()+ms:0}B3d?.update();if(Bpitch)pitchMinute(Bpitch,M,club(M.h),club(M.a),M.ev.filter(e=>e.m===M.m));if(M.m===45&&!live.half){live.half=true;live.paused=true;Bwrite()}if(M.m%5===0)Bwrite();BpaintBroadcast()}if(M.done&&(force||!B3d?.busy)){if((M.bCL!=null||M.bDaily!=null)&&M.gh===M.ga&&!M.pens){const h=club(M.h),a=club(M.a);if(force||G.penGame===false){const r=penAutoShootout(M,h,a);M.pens=r.win;M.penScore=r.score}else{BpenBusy=true;penShootout(M,h,a,r=>{M.pens=r.win;if(r.score)M.penScore=r.score;BpenBusy=false;Btick(true)});return}}BstopBroadcast();delete Bstate().live;if(M.bDaily!=null)BdailyFinish(M);else if(M.bCL!=null)BclFinish(M);else BfinishRound(M)}}
function Bplay(){const b=Bstate();if(b.live){BbroadcastView();return}if(!b.schedule[b.round])return;document.querySelector('.bdialog')?.remove();for(const c of G.clubs)for(const p of c.players){p.inj=Math.max(0,(p.inj||0)-1);p.susp=Math.max(0,(p.susp||0)-1)}const cup=BclTie(),pair=cup||Bnext();if(!pair){BfinishRound();return}const h=club(pair[0]),a=club(pair[1]);BensureXI(me());const M=createMatch(h,a,{kind:'friendly',neutral:!!cup&&b.cl.stage===3,ko:!!cup});M.bRound=b.round;if(cup)M.bCL=b.cl.stage;M.liveMent={[G.me]:'bal'};b.live={M,speed:1,paused:false,half:false};Bwrite();BbroadcastView();window.scrollTo?.(0,0)}
document.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn||!G?.beginner?.live)return;const live=Bstate().live;if(btn.dataset.blive==='subs'){BsubOut=undefined;BsubIn=undefined;BsubDialog();$('bsub-bench')?.scrollIntoView?.({block:'start'});return}if(btn.hasAttribute('data-bsub-out')){BsubOut=+btn.dataset.bsubOut;BsubIn=undefined;BsubDialog();$('bsub-bench')?.scrollIntoView?.({block:'start'});return}if(btn.hasAttribute('data-bsub-in')){const y=document.querySelector('.bdialog')?.scrollTop||0;BsubIn=+btn.dataset.bsubIn;BsubDialog();const d=document.querySelector('.bdialog');if(d)d.scrollTop=y;return}   /* the list stays where it was: the button is already in view */if(btn.dataset.blive==='sub-confirm'){BconfirmSub();return}if(btn.dataset.blive==='pause'){live.paused=!live.paused;Bwrite();BpaintBroadcast()}if(btn.dataset.bspeed){live.speed=btn.dataset.bspeed==='hl'?'hl':+btn.dataset.bspeed;BhlUntil=0;BstartClock();Bwrite();BpaintBroadcast()}if(btn.dataset.bmentality){live.M.liveMent[G.me]=btn.dataset.bmentality;live.M.tadjDirty=true;Bwrite();BpaintBroadcast()}if(btn.dataset.blive==='skip'){BstopBroadcast();while(Bstate().live)Btick(true)}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&G?.beginner){if(Bstate().live){Bstate().live.paused=true;BpaintBroadcast()}Bwrite()}});
window.addEventListener('pagehide',()=>{if(G?.beginner){if(Bstate().live)Bstate().live.paused=true;Bwrite()}});

/* Player ratings of both sides after the final whistle, as a broadcast shows them: the engine's own marks (matchRatings:
   goals, assists, saves, clean sheet, cards, result), home side first like the board above, the best player starred. */
/* With the final score: who scored (minute, assist, penalty or own goal) and who was booked or sent off, each side under
   its own half of the board. */
function BmatchFactsHTML(M){const side=id=>{const goals=M.ev.filter(e=>(e.t==='goal'||e.t==='pen'||e.t==='own')&&e.team===id).map(e=>`<li><span aria-hidden="true">⚽</span><span><strong>${esc(e.name||'')}</strong> <bdi>${e.m}′</bdi>${e.t==='pen'?' · פנדל':e.t==='own'?' · שער עצמי':''}${e.asstName?`<small>בישול: ${esc(e.asstName)}</small>`:''}</span></li>`);
    const cards=M.ev.filter(e=>(e.t==='yellow'||e.t==='red')&&e.team===id).map(e=>`<li><span aria-hidden="true">${e.t==='red'?'🟥':'🟨'}</span><span>${esc(e.name||'')} <bdi>${e.m}′</bdi><small>${e.t==='red'?'כרטיס אדום':'כרטיס צהוב'}</small></span></li>`);
    return `<ul>${goals.join('')}${cards.join('')||''}${goals.length||cards.length?'':'<li class="bmuted"><span></span><span>ללא שערים וכרטיסים</span></li>'}</ul>`};
  return `<section class="bfacts" aria-label="כובשים, מבשלים וכרטיסים">${side(M.h)}${side(M.a)}</section>`}
function BratingsHTML(M){try{if(!M.ratings)matchRatings(M,club(M.h),club(M.a))}catch(e){return ''}
  const order={GK:0,DF:1,MF:2,FW:3};const side=id=>{const c=club(id);return Object.entries(M.ps?.[id]||{}).filter(([,s])=>s.r!=null).map(([pid,s])=>({p:c.players.find(p=>p.id===+pid),s})).filter(x=>x.p).sort((x,y)=>(order[x.p.pos]-order[y.p.pos])||(y.s.min-x.s.min))};
  const hs=side(M.h),as=side(M.a);if(!hs.length&&!as.length)return '';let star=null;for(const x of [...hs,...as])if(!star||x.s.r>star.s.r)star=x;
  const col=(c,rows)=>`<div><h4><i style="background:${esc(c.c1)}"></i>${esc(c.name)}</h4><ol>${rows.map(x=>{const s=x.s,marks=[s.g?'⚽'+(s.g>1?s.g:''):'',s.a?'🅰'+(s.a>1?s.a:''):'',x.p.pos==='GK'&&s.sv?'🧤'+s.sv:'',s.red?'🟥':s.y?'🟨':''].filter(Boolean).join(' ');return `<li class="${x===star?'bstar':''}" title="${esc(fullName(x.p))}"><b class="brate ${s.r>=8?'top':s.r>=7?'good':s.r>=6?'ok':'low'}">${s.r.toFixed(1)}</b><span>${esc(x.p.last||x.p.first)}${x===star?' ⭐':''}</span>${marks?`<small>${marks}</small>`:''}</li>`}).join('')}</ol></div>`;
  return `<section class="bratings" aria-label="ציוני שחקנים"><h3>ציוני שחקנים</h3>${star?`<p class="bratings-star">⭐ שחקן המשחק: <strong>${esc(fullName(star.p))}</strong> <bdi>${star.s.r.toFixed(1)}</bdi></p>`:''}<div class="bratings-cols">${col(club(M.h),hs)}${col(club(M.a),as)}</div></section>`}
function BfinishRound(liveMatch){const b=Bstate();if(!b.schedule[b.round]||(liveMatch&&liveMatch.bRound!==b.round))return;document.querySelector('.bdialog')?.remove();const rounds=b.schedule.length,c=me(),prev={},rr=[];Bstandings().forEach((x,i)=>{prev[x.id]=i+1});let mine;for(const [hid,aid] of b.schedule[b.round]){const h=club(hid),a=club(aid);BensureXI(me());const M=liveMatch&&liveMatch.h===hid&&liveMatch.a===aid?liveMatch:createMatch(h,a,{kind:'friendly',neutral:false});while(!M.done)stepMinute(M);BrecordStats(M);BmoraleAfter(M);rr.push([hid,aid,M.gh,M.ga]);h.P++;a.P++;h.GF+=M.gh;h.GA+=M.ga;a.GF+=M.ga;a.GA+=M.gh;if(M.gh===M.ga){h.D++;a.D++;h.pts++;a.pts++}else{const win=M.gh>M.ga?h:a,lose=win===h?a:h;win.W++;win.pts+=3;lose.L++}if(hid===G.me||aid===G.me){mine=M;if(hid===G.me){const demand=Math.round((c.baseDemand||c.cap*.75)*(1+Math.min(.15,c.W*.01)));const crowd=Math.min(c.cap,demand),fans=b.boost&&b.boost.gate>0;Bledger((fans?'ערב אוהדים · ':'הכנסה מכרטיסים · ')+crowd.toLocaleString('he')+' אוהדים',Math.round(crowd*80*(fans?1.3:1)));if(fans)b.boost.gate--}}}const installment=(total)=>Math.round(total*(b.round+1)/rounds)-Math.round(total*b.round/rounds);Bledger('שכר שחקנים',-installment(Bsum()));Bledger('תפעול האצטדיון',-installment(Boperating()));if(c.sponsor)Bledger('תשלום חסות',installment(c.sponsor.annual));if(b.build&&!--b.build.left){c.cap=b.build.cap;b.build=null}b.round++;G.wk=b.round;b.rnd={s:b.season,r:b.round-1,res:rr,prev};b.last=mine?{h:mine.h,a:mine.a,gh:mine.gh,ga:mine.ga}:null;if(mine)BboardAfter(mine);let gain=null;if(mine)try{gain=BxpMatch(mine)}catch(e){console.warn('engage',e)}try{BeditionRound(mine)}catch(e){console.warn('edition',e)}BclNight();Btab='home';try{BbidRound()}catch(e){console.warn('bids',e)}if(BcareerRound()==='fired')Bleave('fired');else{Bwrite();Brender()}if(mine)Bdialog(`<div class="bresult"><span class="beyebrow">תוצאת המשחק</span><h2 class="bresult-board"><span>${kitSVG(club(mine.h),'lg')}<strong>${esc(club(mine.h).name)}</strong></span>${scoreSides(mine.gh,mine.ga,{label:club(mine.h).name+' '+mine.gh+', '+club(mine.a).name+' '+mine.ga})}<span>${kitSVG(club(mine.a),'lg')}<strong>${esc(club(mine.a).name)}</strong></span></h2>${BxpStripHTML(gain)}${BmatchFactsHTML(mine)}${BratingsHTML(mine)}<p class="bmuted">התנועות הכספיות של המחזור עודכנו. אפשר לראות אותן בכסף וחסויות.</p><div class="bresult-foot">${BresultFoot()}</div></div>`)}
/* Champions get the trophy moment of the full game before the season's numbers. It is shown once a season (b.feted) and
   never over a dialog: a modal dialog sits above every overlay, so the moment comes first and opens what follows. */
function BtitleMoment(then){const b=Bstate();if(typeof openMoment!=='function'||!b||b.round<b.schedule.length||Bplace()!==1||b.feted===b.season)return false;
  try{b.feted=b.season;(b.honours=b.honours||[]).push({season:b.season,what:'אליפות '+BleagueName(),club:me().name});const up=BprMineOf(BprEnsure()),to=up&&up.up&&BcatLeague(up.to);Bwrite();openMoment({id:'b-champ-'+b.season,kind:'champ',comp:BleagueName(),title:'אלופת '+BleagueName(),note:to?'עולים ל'+to.name:'',club:G.me,clubName:me().name,season:npSeasonOf({s:b.season}),shown:true},{onClose:()=>{try{then&&then()}catch(e){console.warn(e)}}});return !!document.getElementById('reveal')}catch(e){console.warn('moment',e);try{closeReveal(true)}catch(x){}return false}}
function Bupgrade(){const n=Blevels.find(l=>l.cap>me().cap);if(!n||Bstate().build)return;const left=me().money-n.cost;Bdialog(`<h2>משדרגים ל־${n.cap.toLocaleString('he')} מקומות?</h2><p>עלות עכשיו: ${Bmoney(n.cost)}</p><p>יישאר בחשבון: ${Bmoney(left)}</p><p>תפעול חדש לשנה: ${Bmoney(n.cap*12)} · העבודה תסתיים בעוד 3 מחזורים.</p>${left>=Bcommitment()+(n.cap-me().cap)*12*Bremaining()?Bbutton('אישור תחילת הבנייה','data-action="build"'):'<p class="bnegative">כדאי לחכות: אין מספיק כסף לשדרוג ולהוצאות שנותרו בעונה.</p>'}`)}
function Bsummary(){try{BpaperSeason()}catch(e){console.warn('paper',e)}const b=Bstate(),ls=b.ledger.filter(x=>x.season===b.season),income=ls.filter(x=>x.amount>0).reduce((s,x)=>s+x.amount,0),expenses=-ls.filter(x=>x.amount<0).reduce((s,x)=>s+x.amount,0);Bdialog(`<span class="beyebrow">עונה ${b.season}</span><h2>מה למדנו מהמספרים?</h2><p>הכנסות: ${Bmoney(income)}</p><p>הוצאות: ${Bmoney(expenses)}</p><p>רווח או הפסד: ${Bmoney(income-expenses)}</p><div class="blearn">${income>=expenses?'שמרת על הכנסות גבוהות מההוצאות. לפני רכש חדש, כדאי לשמור רזרבה.':'ההוצאות היו גבוהות מההכנסות. בעונה הבאה כדאי להשוות את שכר הסגל להכנסות לפני רכישה.'}</div>${(l=>l&&l.tier===1&&!l.cup&&b.round>=b.schedule.length&&Bplace()<=BclPlaces(l)?`<p class="bcl-next"><span class="bstar" aria-hidden="true">★</span> סיימתם בין <bdi>${BclPlaces(l)}</bdi> הראשונות: בעונה הבאה ${esc(me().name)} בליגת האלופות.</p>`:'')(BcatLeague(b.leagueId))}${BprSummaryHTML()}${(v=>`<div class="bverdict"><h3>${v.stay?'ההנהלה':'סוף הדרך במועדון'}</h3><p>${v.text}</p></div>${v.stay?Bbutton(v.renew?'חותם לעונות נוספות':'לעונה הבאה','data-action="newseason"'):Bbutton('להצעות שעל השולחן','data-action="released"')}${v.stay&&v.offers.length?`<div class="boffers"><h3>הצעות ממועדונים אחרים</h3>${v.offers.map(o=>BofferHTML(o,'data-bjob')).join('')}</div>`:''}`)(BseasonVerdict())}`)}
function Btips(){const b=G?.beginner;return !b||b.tips===true||(b.tips!==false&&b.round<2&&b.season<=1)}
function BrenderMain(){document.body.classList.add('beginner');document.body.classList.toggle('btips-off',!Btips());document.body.dataset.btab=Btab;if(G?.beginner?.live){BbroadcastView();return}if(BDAILY){BdailyRender();return}if(G?.beginner?.out){document.getElementById('top')?.classList.add('hide');document.getElementById('nav')?.classList.add('hide');document.getElementById('main').innerHTML=BoutHTML();return}document.getElementById('top')?.classList.add('hide');document.getElementById('nav')?.classList.add('hide');const main=document.getElementById('main');if(!G?.beginner&&Bstart.step!=='name'){main.innerHTML=`<div class="bpick-page"><div class="bapp"><header class="btop"><a class="bbrand" href="beginner.html">GOALASSO<span>START</span></a><span class="bpill">מצב מתחילים</span></header>${BstartHTML()}<p role="status">${esc(Bnotice)}</p></div></div>`;return}
if(!G?.beginner){main.innerHTML=`<div class="bapp"><header class="btop"><a class="bbrand" href="beginner.html">GOALASSO<span>START</span></a><span class="bpill">מצב מתחילים</span></header><section class="bopening"><video autoplay muted loop playsinline poster="assets/intro-poster.jpg" aria-hidden="true"><source src="assets/intro.webm" type="video/webm"><source src="assets/intro.mp4" type="video/mp4"></video><div class="bopening-copy"><span class="bpill">הכדורגל שלך מתחיל כאן</span><h1>האורות נדלקים.<br>המועדון מחכה לך.</h1><p>חתום על חוזה. בנה סגל. הובל את המועדון לניצחון.</p>${Bbutton('מתחילים קריירה ←','data-bchoose')}<span class="bopening-note">שחקנים אמיתיים · משחקים חיים · החלטות שלך</span></div></section>${BstartHTML()}${BdailyEntryHTML()}<p role="status">${esc(Bnotice)}</p></div>`;return}const c=me();main.innerHTML=`<div class="bapp"><header class="btop ahud"><div class="bclubname">${Bhex(c)}<div><strong>${esc(c.name)}</strong><small>${esc(BleagueName())} · מקום <bdi>${Bplace()}</bdi></small>${BxpHudHTML()}</div></div><button type="button" class="achip" data-tab="finance" aria-label="כסף זמין במועדון">${Bui('coins')}${Bmoney(c.money)}</button><a class="bbrand" href="beginner.html">GOALASSO<span>START</span></a><span class="bpill">מצב מתחילים</span></header><nav class="bnav anav" aria-label="תפריט ראשי">${BnavHTML()}</nav><main class="bcontent">${({home:Bhome,squad:Bsquad,league:Bleague,market:Bmarket,training:Btraining,finance:Bfinance,stadium:Bstadium}[Btab]||Bhome)()}</main><footer class="bfooter"><span role="status">${esc(Bnotice)}</span><button type="button" class="bbtn secondary" data-bsave>שמור שוב</button><span>GOALASSO START · לומדים דרך המשחק</span><button type="button" class="blink" data-action="tips">${Btips()?'להסתיר טיפים':'להציג טיפים'}</button><button type="button" class="blink" data-action="entry">לדף הכניסה · משחק רשת</button>${buildStampHTML()}</footer></div>`}
/* ---- the newspaper (the front page of the full game) in a beginner career ----
   A story is written when something happens to the coach or to his club: he is appointed, resigns or is dismissed,
   a player signs or is sold, a sponsor comes in, a title is won, Europe ends, another club asks for him. It is
   kept in G.paper (the archive behind the home screen's tile), and his own news also opens as a front page —
   never over a dialog and never during a match: the queue (b.paperPop) waits until the screen is free. */
let BpaperT=0;
function Bpaper(kind,h,sub,body,ev,pop){const b=Bstate();if(!b)return;const st=Object.assign({wk:b.round,s:b.season,kind,h,sub,body,team:(ev&&ev.clubId)||G.me},ev?{ev}:{});G.paper=[st,...(G.paper||[])].slice(0,40);if(pop!==false)b.paperPop=[...(b.paperPop||[]),st].slice(-3)}
function BpaperSoon(){clearTimeout(BpaperT);BpaperT=setTimeout(()=>{try{BpaperFlush()}catch(e){console.warn('paper',e)}},80)}
function BpaperFlush(){const b=G&&G.beginner;if(!b||!b.paperPop||!b.paperPop.length||b.live||NPM)return;if(BDAILY||document.querySelector('.bdialog,.lg-overlay,#pcup,.room-dialog,.pg,#reveal,#bpack'))return;const sp=document.getElementById('splash');if(sp&&!sp.classList.contains('hide')&&!sp.classList.contains('out'))return;
  const st=b.paperPop.shift();Bwrite();openFrontPage(st,{live:false,more:b.paperPop.length,onNext:BpaperFlush,onClose:BpaperSoon})}
const BgoalPlain=k=>k.goal<=1?'לזכות באליפות':k.zone==='stay'?`להישאר בליגה, כלומר מקום ${k.goal} או גבוה ממנו`:`לסיים במקום ${k.goal} או גבוה ממנו`;
function BpaperAppoint(from){const b=Bstate(),k=b.contract,c=me();if(!k)return;const coach=b.coach||'המאמן',goal=BgoalPlain(k),moved=from&&from!==c.name;
  Bpaper('מועדון',`${coach} מונה למאמן ${c.name}`,`חוזה ל־${k.years} עונות. היעד: ${goal}`,
   `${c.name} הציגה היום את המאמן החדש שלה, ${coach}${moved?`, שמגיע אחרי התקופה שלו ב${from}`:''}. ההנהלה הציבה יעד ברור: ${goal}. ${pick(['האוהדים כבר מחכים למשחק הראשון.','בחדר ההלבשה מדברים על התחלה חדשה.','במועדון מצפים לראות את טביעת האצבע שלו כבר בשבועות הקרובים.'])} העבודה מתחילה באימון הקרוב.`,
   {type:'appoint',manager:coach,club:c.name,clubId:c.id,years:k.years,goal,q:pick(['באתי לבנות קבוצה שהאוהדים יתגאו בה','אני מכיר את הציפיות כאן, והן לא מפחידות אותי','מעכשיו הדשא ידבר'])})}
function BpaperDepart(why){const b=Bstate(),c=me(),coach=b.coach||'המאמן',pos=Bplace(),n=b.league.length,fired=why!=='resigned';
  Bpaper('מועדון',fired?`${c.name} נפרדת מ${coach}`:`${coach} התפטר מ${c.name}`,`אחרי ${b.round} מחזורים, במקום ${pos} בטבלה`,
   fired?`הנהלת ${c.name} הודיעה על סיום דרכו של ${coach} במועדון. הקבוצה במקום ${pos} מתוך ${n}, ובהנהלה הסבירו שהתוצאות לא עמדו בציפיות. ${pick(['האוהדים חלוקים בדעתם על ההחלטה.','השחקנים נפרדו ממנו בחדר ההלבשה.','במועדון כבר מחפשים מחליף.'])} כמה מועדונים כבר בודקים אם הוא פנוי.`
        :`${coach} הודיע להנהלת ${c.name} שהוא עוזב את תפקידו. הקבוצה במקום ${pos} מתוך ${n}. ${pick(['ההודעה הפתיעה את השחקנים.','בהנהלה ניסו לשכנע אותו להישאר.','האוהדים נפרדו ממנו בחום.'])} כמה מועדונים כבר בודקים אם הוא פנוי.`,
   {type:'depart',manager:coach,club:c.name,clubId:c.id,record:`${c.W} נצ׳ · ${c.D} תיקו · ${c.L} הפ׳`,place:`${pos} מתוך ${n}`,why,q:fired?'נתתי הכול. אני מאחל למועדון הצלחה':'הרגשתי שהגיע הזמן לאתגר חדש'})}
function BpaperSign(p,from,fee,loan){const c=me(),name=fullName(p);
  Bpaper('העברות',loan?`${name} מצטרף בהשאלה ל${c.name}`:`${name} חתם ב${c.name}`,
   from?(loan?`מגיע מ${from.name} עד סוף העונה${fee?` · דמי השאלה ${NIS(fee)}`:''}`:`${c.name} שילמה ${NIS(fee)} ל${from.name}`):'הצטרף כשחקן חופשי',
   `${name}, ${POSHE[p.pos]} בן ${p.age}${from?` שמגיע מ${from.name}`:''}, הוא ${loan?'החיזוק':'הרכש'} החדש של ${c.name}. ${pick(OPENERS)} ${p.age<=23?'במועדון מאמינים שהוא יהפוך לאחד הנכסים הגדולים של הקבוצה.':'במועדון מאמינים שהוא יביא איתו ניסיון וביטחון.'}`,
   loan?{type:'loan',pid:p.id,vid:playerVisualId(p)||null,player:name,pos:p.pos,age:p.age,no:p.no||null,club:c.name,clubId:c.id,parent:from?from.name:null,until:'העונה',buy:null}
       :{type:'sign',pid:p.id,vid:playerVisualId(p)||null,player:name,pos:p.pos,age:p.age,no:p.no||null,club:c.name,clubId:c.id,from:from?from.name:null,fee:fee||null,free:!from,years:null})}
function BpaperSale(p,buyer,fee){const c=me(),name=fullName(p);
  Bpaper('העברות',`${name} עוזב את ${c.name}`,`${buyer.name} שילמה ${NIS(fee)}`,`${c.name} נפרדת מ${name} (${p.age}). ${pick(['ההנהלה רואה בעסקה הזדמנות לרענן את הסגל.','המכירה תאפשר למועדון לחזק עמדות אחרות.','האוהדים חלוקים: יש שמצטערים על הפרידה ויש שמברכים על הסכום.'])} ב${buyer.name} מקווים שהוא ישתלב מהר.`,
   {type:'sale',pid:p.id,vid:playerVisualId(p)||null,player:name,pos:p.pos,age:p.age,club:c.name,clubId:c.id,buyer:buyer.name,buyerId:buyer.id,fee})}
function BpaperSponsor(name,annual){const c=me();Bpaper('כספים',`${c.name} חתמה עם ${name}`,`חסות חולצה של ${NIS(annual)} לעונה`,`הלוגו של ${name} יופיע על חולצת ${c.name} כבר במשחק הבא. במועדון מסבירים שהכסף יעזור לשלם את שכר השחקנים.`,{type:'sponsor',sponsor:name,club:c.name,clubId:c.id,annual,years:1})}
/* a result is news only when it is a rout either way, and it goes to the archive without opening by itself */
function BpaperResult(M){const c=me(),b=Bstate(),home=M.h===G.me,opp=club(home?M.a:M.h),gf=home?M.gh:M.ga,ga=home?M.ga:M.gh;if(!opp||Math.abs(gf-ga)<3)return;const sc=[...new Set(M.ev.filter(e=>(e.t==='goal'||e.t==='pen')&&e.team===c.id).map(e=>e.name).filter(Boolean))];
  if(gf>ga)Bpaper('ליגה',`${c.name} ${pick(['ריסקה','פירקה','הביסה','מחצה'])} את ${opp.name} ${gf}:${ga}`,`מחזור ${b.round+1}: ערב גדול ל${c.name}`,`${sc.length?`השערים: ${sc.join(', ')}. `:''}${pick(['הקהל חגג עד השריקה.','המאמן יצא מהמשחק מרוצה מאוד.','זו תוצאה שתיזכר לאורך העונה.'])}`,null,false);
  else Bpaper('ליגה',`ערב שחור ל${c.name}`,`הפסד ${ga}:${gf} ל${opp.name} במחזור ${b.round+1}`,`${c.name} ספגה ${ga} שערים${home?' מול הקהל הביתי':''}. ${pick(['בסביבת המועדון מדברים על לחץ על המאמן.','ההנהלה מבקשת תגובה כבר במשחק הבא.','האוהדים דורשים שינוי.'])}`,null,false)}
function BpaperCL(M,st,won,final){const c=me(),home=M.h===G.me,opp=club(home?M.a:M.h),score=`${M.gh}:${M.ga}`,pens=M.gh===M.ga,tail=`${score}${pens?' (פנדלים)':''} מול ${opp.name}`;
  if(final&&won)Bpaper('אירופה',`${c.name} אלופת אירופה!`,`${tail} בגמר ליגת האלופות`,`חגיגות ענק אחרי השריקה: ${c.name} מניפה את הגביע עם האוזניים הגדולות. ${pick(['העיר לא תישן הלילה.','זה הלילה הגדול בתולדות המועדון.'])}`,{type:'cup',comp:'ליגת האלופות',club:c.name,clubId:c.id,score,opp:opp.name,pens});
  else if(!won)Bpaper('אירופה',`המסע האירופי של ${c.name} נגמר`,`${tail} ב${BCL_STAGES[st]}`,`${c.name} נפרדת מליגת האלופות ב${BCL_STAGES[st]}. ${pick(['המאמן: "נלמד מזה ונחזור חזקים יותר".','עכשיו כל הכוח לליגה.'])}`);
  else Bpaper('אירופה',`${c.name} עלתה ל${BCL_STAGES[st+1]}`,tail,`לילה אירופי גדול: ${c.name} ממשיכה בליגת האלופות, והפרס כבר בדרך לקופת המועדון.`,null,false)}
function BpaperOffer(o){const b=Bstate(),c=me(),coach=b.coach||'המאמן';Bpaper('מועדון',`${o.name} רוצה את ${coach}`,`הצעה באמצע העונה למאמן של ${c.name}`,`הנהלת ${o.name} פנתה אל ${coach} אחרי הפתיחה המוצלחת שלו ב${c.name}. ההצעה בתוקף עד מחזור ${o.until}. ${pick(['ב'+c.name+' מקווים שיישאר.','האוהדים עוקבים בדריכות.'])}`)}
function BpaperSeason(){const b=Bstate();if(b.round<b.schedule.length||b.paperSeason===b.season)return;b.paperSeason=b.season;const t=Bstandings(),ch=t[0],sec=t[1];if(!ch)return;const mine=ch.id===G.me;
  Bpaper('ליגה',`${ch.name} אלופת ${BleagueName()}`,mine?'העונה הסתיימה במקום הראשון':`${ch.pts} נקודות בסיום העונה`,`${ch.name} סיימה את העונה במקום הראשון עם ${ch.pts} נקודות${sec?`, לפני ${sec.name}`:''}. ${mine?'חגיגות ענק בעיר.':`${me().name} סיימה במקום ${Bplace()}.`}`,{type:'champ',club:ch.name,clubId:ch.id,season:`עונה ${b.season}`,pts:ch.pts,second:sec?sec.name:null},mine)}
/* BpaperArchive: in edition.js, where the round's edition leads the list */
function Brender(){BrenderMain();BpaperSoon()}
render=Brender;
document.addEventListener('input',e=>{if(e.target.id==='bcoach'){Bstart.name=e.target.value;Bstart.err=''}if(e.target.id==='bclubsearch'){Bstart.q=e.target.value;const box=document.getElementById('bclubhits');if(box)box.innerHTML=BclubHitsHTML();else{const pos=e.target.selectionStart;Brender();const el=document.getElementById('bclubsearch');if(el){el.focus();el.setSelectionRange(pos,pos)}}}if(e.target.id==='bsearch'){Bquery=e.target.value;const box=document.getElementById('bmarketres');if(box)box.innerHTML=BmarketResultsHTML(BmarketPool(),BmarketHome());else{const pos=e.target.selectionStart;Brender();const el=document.getElementById('bsearch');if(el){el.focus();el.setSelectionRange(pos,pos)}}}if(e.target.id==='boffer'){const f=Bfind(Bselected);document.getElementById('bfirstcost').innerHTML=Bmoney(Math.max(0,Number(e.target.value)||0)+Byear(f.p))}});
document.addEventListener('change',e=>{if(e.target.id==='bformation'&&!Bstate().live){me().formation=e.target.value;me().lineup=autoLineupFor(me());Bwrite();Brender()}if(e.target.id==='bpos'){Bpos=e.target.value;Brender()}if(e.target.id==='bsort'){Bsort=['ovr','desc'].includes(e.target.value)?e.target.value:'asc';try{localStorage.setItem('goalasso.beginner.sort',Bsort)}catch(err){}Brender()}if(e.target.id==='bmleague'){Bmleague=e.target.value;Brender();Bwrite()}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.hasAttribute('data-bchoose')){$('bstart')?.scrollIntoView?.({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});$('bcoach')?.focus({preventScroll:true});return}if(BstartClick(el))return;if(el.hasAttribute('data-bsave')){Bwrite();Brender();return}if(el.hasAttribute('data-bclose')){el.closest('dialog')?.remove();BpaperSoon();return}if(el.dataset.bpaper!=null){const st=(G.paper||[])[+el.dataset.bpaper];el.closest('dialog')?.remove();if(st)openFrontPage(st,{live:false});return}if(el.dataset.start){Bcreate(el.dataset.start);return}if(!G?.beginner)return;try{const stored=JSON.parse(localStorage.getItem(BK)||'null');if(stored&&stored.rev!==BsaveRev){Bnotice='הקריירה עודכנה בחלון אחר. רענן את העמוד לפני המשך.';Brender();return}}catch(err){}if(el.dataset.tab){Btab=el.dataset.tab;Brender();window.scrollTo?.(0,0)}if(el.dataset.category){Bcategory=el.dataset.category;Brender()}if(el.dataset.bhomeleague){const l=BcatLeague(el.dataset.bhomeleague),h=BmarketHome();if(l&&h&&h.c.leagues.includes(l)){Bhomeleague=l.id;const n=G.clubs.length;BensureLeague(l);if(G.clubs.length!==n)Bwrite();Brender()}}if(el.dataset.player)Bdetail(+el.dataset.player);if(el.dataset.sponsorB&&!me().sponsor){const offer=Bstate().sponsorOffers.find(x=>x.id===el.dataset.sponsorB),brand=SPONSOR_CATALOG.find(x=>x.id===offer?.id);if(brand){me().sponsor={name:brand.name,brandId:brand.id,annual:offer.annual,years:1};try{Bcount('sponsors')}catch(e){}try{BpaperSponsor(brand.name,offer.annual)}catch(e){console.warn('paper',e)}Bwrite();Brender()}}if(el.dataset.sign)Bsign(+el.dataset.sign,+el.dataset.fee,el.dataset.loan==='1');if(el.hasAttribute('data-lineup-slot'))BchooseLineup(+el.dataset.lineupSlot);if(el.dataset.lineupIn)BsetLineup(+el.dataset.lineupIn);if(el.dataset.sell)BsaleDialog(+el.dataset.sell);const a=el.dataset.action;if(a==='sell-confirm')BconfirmSale();if(a==='edit-lineup'){el.closest('dialog')?.remove();Btab='squad';Brender()}if(a==='auto'){me().lineup=autoLineupFor(me());Bwrite();Brender()}if(a==='offer')Boffer();if(a==='loan')Boffer(true);if(a==='counter'&&Bcounter){document.getElementById('boffer').value=Bcounter;document.getElementById('bfirstcost').innerHTML=Bmoney(Bcounter+Byear(Bfind(Bselected).p))}if(a==='signed'){el.closest('dialog')?.remove();Btab='squad';Brender()}if(el.dataset.bjob){const b=Bstate(),o=[b.offer,...((b.out&&b.out.offers)||[]),...((b.verdict&&b.verdict.offers)||[])].find(x=>x&&x.key===el.dataset.bjob);if(o){el.closest('dialog')?.remove();BtakeJob(o)}return}if(a==='resign'){Bdialog(`<span class="beyebrow">התפטרות</span><h2>לעזוב את ${esc(me().name)}?</h2><p>העונה במועדון הזה תסתיים עבורך, ותבחר מועדון חדש מבין ההצעות שיגיעו. אי אפשר לבטל.</p>${Bbutton('כן, אני מתפטר','data-action="resign-yes"')}<button type="button" class="blink" data-bclose>נשאר במועדון</button>`);return}if(a==='resign-yes'){el.closest('dialog')?.remove();Bleave('resigned');return}if(a==='released'){el.closest('dialog')?.remove();Bleave('fired');return}if(a==='bout-leagues'){const b2=Bstate();if(b2.out){b2.out.pick=true;Bwrite();Brender()}return}
   if(a==='bout-back'){const b2=Bstate();if(b2.out){b2.out.pick=false;if(!b2.out.offers.length){b2.out.offers=b2.out.first||[];b2.out.league=null}Bwrite();Brender()}return}
   if(el.dataset.boutleague){const b2=Bstate();if(b2.out){b2.out.league=el.dataset.boutleague;b2.out.offers=BleagueOffers(el.dataset.boutleague,b2.out.why,3);b2.out.pick=false;Bwrite();Brender()}return}
   if(a==='paper'){if(BeditionFresh())BeditionOpen();else BpaperArchive();return}if(a==='decline'){Bstate().offer=null;Bwrite();Brender();return}if(a==='tips'){const b=Bstate();b.tips=!Btips();Bwrite();Brender();return}if(a==='entry'){if(Bstate().live)return;Bwrite();showSplash();return}if(a==='prematch')Bprematch();if(a==='play')Bplay();if(a==='upgrade')Bupgrade();if(a==='build'){const n=Blevels.find(l=>l.cap>me().cap);if(n&&!Bstate().build&&me().money-n.cost>=Bcommitment()+(n.cap-me().cap)*12*Bremaining()){Bledger('הרחבת האצטדיון',-n.cost);Bstate().build={cap:n.cap,left:3};try{Bcount('builds')}catch(e){}Bwrite();el.closest('dialog')?.remove();Brender()}}if(a==='season'){if(!BtitleMoment(()=>Bsummary()))Bsummary()}if(a==='newseason'&&Bstate().round>=Bstate().schedule.length){const b=Bstate();for(const l of b.loans){const p=me().players.find(p=>p.id===l.pid);if(p){me().players=me().players.filter(x=>x.id!==p.id);club(l.club).players.push(p)}}b.loans=[];BstayOn();BreleaseToFree();{const l=BcatLeague(b.leagueId);b.clq=l&&l.tier===1&&!l.cup?{league:l.id,season:b.season,keys:Bstandings().slice(0,BclPlaces(l)).map(c=>c.bkey)}:null}let star=null;try{star=BbidStar(true)}catch(e){console.warn('bids',e)}let moved=null;try{moved=BprApply()}catch(e){console.warn('moves',e)}b.season++;G.season=b.season;try{BprSettle(moved)}catch(e){console.warn('moves',e)}me().sponsor=null;b.sponsorOffers=pickSponsorBrands(me(),3).map(x=>({id:x.id,annual:Math.round(Math.max(Bsum()*.4,300000)),years:1}));Bseason();try{b.bid=null;b.bidNo={};b.bidAt=null;if(star)BbidMake(star)}catch(e){console.warn('bids',e)}try{BmsFill()}catch(e){}Bwrite();el.closest('dialog')?.remove();Brender()}});
/* Beginner club management and season statistics. */
let BlineupSlot=null;
function BensureStats(){const b=Bstate();if(!b.playerStats){b.playerStats={};b.recordedMatches={};b.statsStartRound=b.round||0}b.recordedMatches=b.recordedMatches||{}}
function Bstandings(){return Bstate().league.map(id=>club(id)).filter(Boolean).sort((a,b)=>b.pts-a.pts||(b.GF-b.GA)-(a.GF-a.GA)||b.GF-a.GF||a.name.localeCompare(b.name,'he'))}
/* ---- morale: a player who is left out loses heart, and playing gives it back ----
   The beginner career had no morale at all: every player kept the number he was made with. After each match of the coach's own club (league
   or Europe, never the daily challenge) whoever played takes the result (+3, +1, −1; +1 for a win once he is already at 85) and three more
   when it ended a wait of three matches; whoever was fit and was not used counts one more match out (p.bOut) and loses according to what he
   may expect: one of the squad's eleven best 3 a match, the next five 2, everybody else and a second goalkeeper 1. Each of the three has a
   floor (15, 30, 42), so a third-choice player gets low and never into crisis for being third choice — with twenty-five players and sixteen
   shirts, nine sit out every match whatever the coach does. Injured and suspended players are left alone, and a summer lifts whoever is
   under 60 (Bseason).
   Nothing reads morale but effOvr (±1.75 rating at the ends), which every match already uses. */
function BmoraleRank(c){const xs=c.players.slice().sort((a,b)=>b.ovr-a.ovr),r={};xs.forEach((p,i)=>{r[p.id]=i});const gk=xs.find(p=>p.pos==='GK');return {r,gk:gk?gk.id:null}}
function BmoraleKind(p,k){return p.pos==='GK'&&p.id!==k.gk?2:k.r[p.id]<11?0:k.r[p.id]<16?1:2}
function BmoraleAfter(M){const b=Bstate(),c=me();if(!b||b.daily||!c||!M||M.bMor||(M.h!==c.id&&M.a!==c.id))return;M.bMor=1;
  const home=M.h===c.id,gf=home?M.gh:M.ga,ga=home?M.ga:M.gh,played=new Set([...((M.xi&&M.xi[c.id])||[]).map(e=>e.pid),...((M.used&&M.used[c.id])||[])]),k=BmoraleRank(c);
  for(const p of c.players){const m=p.morale??65;
    if(played.has(p.id)){p.morale=clamp(m+(gf>ga?(m>=85?1:3):gf===ga?1:-1)+((p.bOut||0)>=3?3:0),10,100);p.bOut=0}
    else if(!p.inj&&!p.susp){p.bOut=(p.bOut||0)+1;const kind=BmoraleKind(p,k);p.morale=Math.max(Math.min(m,[15,30,42][kind]),m-[3,2,1][kind])}}}
/* fitness and morale as two small meters, wherever a player is chosen: the number and the word say it, the colour only repeats them */
function BcondHTML(p,energy){const fit=Math.round(energy==null?(p.fit??100):energy),m=Math.round(p.morale??65),fc=fit>=82?'good':fit>=70?'warn':'bad',mc=m>=70?'good':m>=50?'mid':m>=35?'warn':'bad';
  return `<span class="bcond"><span class="bmeter ${fc}" data-fit="${fit}"><i>כושר</i><b><u style="width:${fit}%"></u></b><em><bdi>${fit}%</bdi></em></span><span class="bmeter ${mc}" data-morale="${m}"><i>מורל</i><b><u style="width:${m}%"></u></b><em>${moraleWord(m)}</em></span></span>`}
const BoutText=p=>(p.bOut||0)>=3?`לא שיחק <bdi>${p.bOut}</bdi> משחקים`:'';
function BrecordStats(M){BensureStats();const b=Bstate(),key=[b.season,b.round,M.h,M.a].join(':');if(b.recordedMatches[key])return;const add=(pid,cid,field)=>{const p=club(cid)?.players.find(p=>p.id===pid);if(!p)return;const s=b.playerStats[pid]||(b.playerStats[pid]={pid,name:fullName(p),clubId:cid,goals:0,assists:0});s.clubId=cid;s[field]++};for(const e of M.ev){if(e.t==='goal'||e.t==='pen'){add(e.pid,e.team,'goals');if(e.t==='goal'&&e.asst)add(e.asst,e.team,'assists')}}b.recordedMatches[key]=true}
function Bleaders(field){BensureStats();return Object.values(Bstate().playerStats).filter(s=>s[field]>0).sort((a,b)=>b[field]-a[field]||b.goals-a.goals||a.name.localeCompare(b.name,'he'))}
function Bleague(){BensureStats();const b=Bstate();const leaderboard=(field,title)=>`<section class="bpanel"><h2>${title}</h2><div class="bleaders">${Bleaders(field).map((s,i)=>{const f=Bfind(s.pid);return `<button class="bleader" data-player="${s.pid}"><b>${i+1}</b>${f?Bportrait(f.p,f.c):''}<span><strong>${esc(s.name)}</strong><small>${esc(club(s.clubId)?.name||'')}</small></span><b class="bleader-count">${s[field]}</b></button>`}).join('')||'<p>עדיין אין נתונים. הטבלה תתעדכן אחרי המשחקים.</p>'}</div></section>`;return `${Bheader('כל הליגה במקום אחד','טבלאות הליגה',`עונה ${b.season} · הושלמו ${b.round} מתוך ${b.schedule.length} מחזורים`)}<section class="bpanel"><h2>טבלת הליגה</h2><div class="btable-wrap"><table class="bleague-table"><thead><tr><th>#</th><th>קבוצה</th><th>מש׳</th><th>נצ׳</th><th>תיקו</th><th>הפ׳</th><th>שערים</th><th>הפרש</th><th>נק׳</th></tr></thead><tbody>${(z=>Bstandings().map((c,i,t)=>`<tr class="${c.id===G.me?'bmyclub':''} ${(k=>k?'bz-'+k:'')(BprZoneOf(i,t.length,z)||(i<z.cl?'cl':''))}"><td>${i+1}</td><th>${esc(c.name)}${c.id===G.me?' ★':''}</th><td>${c.P}</td><td>${c.W}</td><td>${c.D}</td><td>${c.L}</td><td><bdi>${c.GF}:${c.GA}</bdi></td><td><bdi>${c.GF-c.GA}</bdi></td><td><strong>${c.pts}</strong></td></tr>`).join(''))((l=>Object.assign(BprZones(l),{cl:l&&l.tier===1&&!l.cup?BclPlaces(l):0}))(BcatLeague(b.leagueId)))}</tbody></table></div>${BprLegendHTML()}<p class="bmuted">הדירוג נקבע לפי נקודות, הפרש שערים ואז שערי זכות. אפשר לגלול את הטבלה לצדדים.</p></section>${BclLeagueHTML()}${b.statsStartRound>0?`<p class="blearn">בשמירה הזאת נתוני הכובשים והמבַשלים נאספים ממחזור ${b.statsStartRound+1}. תוצאות המחזורים הקודמים נשמרו בטבלת הליגה, אך פירוט הכובשים לא נשמר בגרסה הישנה.</p>`:''}<div class="btwocol">${leaderboard('goals','מלך השערים')}${leaderboard('assists','מלך הבישולים')}</div>`}
function BensureXI(c=me()){ensureLineup(c);const used=new Set(),slots=slotsFor(c.formation),av=available(c);c.lineup=slots.map((slot,i)=>{let p=av.find(p=>p.id===c.lineup[i]&&!used.has(p.id)&&(slot!=='GK'||p.pos==='GK'));if(!p)p=av.filter(p=>!used.has(p.id)&&(slot!=='GK'||p.pos==='GK')).sort((a,b)=>((b.pos===slot?100:0)+b.ovr)-((a.pos===slot?100:0)+a.ovr))[0];if(p)used.add(p.id);return p?.id??null});return c.lineup}
function Bsquad(){const c=me();BensureXI(c);const slots=slotsFor(c.formation),pos=Bstandings().findIndex(x=>x.id===c.id)+1;return `${Bheader('המועדון שלי',esc(c.name),`${esc(c.country)} · ${esc(c.stadium)} · מקום ${pos} בליגה`)}<div class="btoolbar">${Bbutton('טבלת הליגה','data-tab="league"','secondary')}${Bbutton('בחר הרכב מומלץ','data-action="auto"','secondary')}</div><div class="bclub-summary"><span>${c.players.length} שחקנים</span><span>${c.pts} נקודות</span><span>${c.W} ניצחונות</span><span>שווי סגל ${Bmoney(c.players.reduce((n,p)=>n+Bvalue(p),0))}</span></div><section class="bpanel"><div class="btoolbar"><h2>ההרכב שלי</h2><label>מערך <select id="bformation">${Object.keys(FORMATIONS).map(f=>`<option ${c.formation===f?'selected':''}>${f}</option>`).join('')}</select></label></div><p>לחץ על שחקן במגרש כדי להחליף אותו בשחקן מהספסל. השינויים נשמרים למשחק הבא.</p><div class="bformation formation-board" style="--club-color:${esc(c.c1)};--club-ink:${inkFor(c.c1)}"><div class="formation-grass">${pitchLines()}</div>${slots.map((slot,i)=>{const l=slotLayout(c.formation)[i],x=50+(l.x-50)*(.80+l.y*.002),y=18+l.y*.72;const p=c.players.find(p=>p.id===c.lineup[i]);return `<button class="bformation-player" style="left:${x}%;top:${y}%" data-lineup-slot="${i}" aria-label="${esc(p?fullName(p):'עמדה פנויה')}">${p?formationPortraitHTML(c,p,'beginner'+i):'<span>＋</span>'}<strong>${esc(p?p.last||p.first:'עמדה פנויה')}</strong><small>${POSHE[slot]}${p?' · '+p.ovr:''}</small></button>`}).join('')}</div></section><h2>כל הסגל · ${c.players.length} שחקנים</h2><p class="bmuted">בפרטי שחקן אפשר לראות את הנתונים שלו ולהציע אותו למכירה.</p><div class="bplayers">${c.players.map(p=>Bplayer(p,c)).join('')}</div>`}
function BchooseLineup(slot){if(Bstate().live)return;BensureXI();if(!Number.isInteger(slot)||slot<0||slot>=11)return;BlineupSlot=slot;const c=me(),position=slotsFor(c.formation)[slot],out=c.players.find(p=>p.id===c.lineup[slot]);const candidates=available(c).filter(p=>!c.lineup.includes(p.id)&&(position!=='GK'||p.pos==='GK')).sort((a,b)=>((b.pos===position?100:0)+b.ovr)-((a.pos===position?100:0)+a.ovr));Bdialog(`<h2>שינוי בהרכב · ${POSHE[position]}</h2><p>${out?esc(fullName(out))+' יֵרד לספסל.':'בחר שחקן לעמדה הפנויה.'}</p>${out?Bbutton('פרטי '+fullName(out),`data-player="${out.id}"`,'secondary'):''}<h3>מי ייכנס להרכב?</h3><div class="bsub-list">${candidates.map(p=>`<button class="bsub-player" data-lineup-in="${p.id}">${Bportrait(p,c)}<span><strong>${esc(fullName(p))}</strong><small>${POSHE[p.pos]} · דירוג ${p.ovr}${slotPenalty(p,position)>0?' · לא בעמדה הטבעית':''}${BoutText(p)?' · '+BoutText(p):''}</small>${BcondHTML(p)}</span></button>`).join('')||'<p>אין שחקן זמין מתאים בספסל.</p>'}</div>`)}
function BsetLineup(pid){if(Bstate().live||BlineupSlot===null)return false;const c=me(),p=available(c).find(p=>p.id===pid),slot=slotsFor(c.formation)[BlineupSlot];if(!p||!slot||c.lineup.includes(pid)||(slot==='GK'&&p.pos!=='GK'))return false;const lineup=c.lineup.slice();lineup[BlineupSlot]=pid;if(c.country==='ישראל'&&lineup.filter(id=>c.players.find(p=>p.id===id)?.foreign).length>MAX_FOREIGN_XI){Bdialog('<h2>מגבלת זרים</h2><p>ניתן לשלב עד שישה זרים בהרכב.</p>');return false}c.lineup=lineup;BlineupSlot=null;Bwrite();document.querySelector('.bdialog')?.remove();Btab='squad';Brender();return true}
function BsaleBlocked(p){if(Bstate().live)return 'אפשר למכור שחקנים בין המשחקים.';if(Bstate().loans.some(l=>l.pid===p.id))return 'השחקן מושאל למועדון שלך ואינו בבעלותך.';if(me().players.length<=14)return 'צריך להשאיר לפחות 14 שחקנים בסגל.';if(p.pos==='GK'&&me().players.filter(p=>p.pos==='GK').length<=2)return 'צריך להשאיר לפחות שני שוערים בסגל.';return ''}
function BsaleDialog(pid){const p=me().players.find(p=>p.id===pid);if(!p)return;const blocked=BsaleBlocked(p);if(blocked){Bdialog(`<h2>מכירת שחקן</h2><p>${blocked}</p>`);return}const fee=Math.max(50000,Math.round(Bvalue(p)*.9/50000)*50000);const buyer=G.clubs.filter(c=>c.id!==G.me&&c.players.length<35&&c.money>=fee&&c.money-fee>=Byear(p)*Bremaining()).sort((a,b)=>Math.abs(strength(a)-p.ovr)-Math.abs(strength(b)-p.ovr))[0];if(!buyer){Bdialog('<h2>אין כרגע הצעה מתאימה</h2><p>לא נמצא מועדון עם תקציב ומקום בסגל. נסה שוב בהמשך העונה.</p>');return}Bstate().saleOffer={pid,buyer:buyer.id,fee};Bwrite();Bdialog(`<div class="bprofile">${Bportrait(p,me())}<h2>הצעה עבור ${esc(fullName(p))}</h2></div><p>${esc(buyer.name)} מציעה לרכוש את השחקן.</p><div class="btransaction"><span>שווי שוק</span>${Bmoney(Bvalue(p))}</div><div class="btransaction"><span>דמי ההעברה שתקבל</span>${Bmoney(fee)}</div><div class="btransaction"><span>שכר שנתי שייחסך</span>${Bmoney(Byear(p))}</div><div class="blearn">אחרי המכירה יהיו בחשבון ${Bmoney(me().money+fee)}. השחקן יעבור למועדון הרוכש ויֵצא מההרכב שלך.</div>${Bbutton('אישור מכירת השחקן','data-action="sell-confirm"')}`)}
function BconfirmSale(){const o=Bstate().saleOffer;if(!o)return false;const c=me(),p=c.players.find(p=>p.id===o.pid),buyer=club(o.buyer);if(!p||BsaleBlocked(p)||!buyer||buyer.id===c.id||buyer.players.length>=35||buyer.money<o.fee||!Number.isFinite(o.fee)||o.fee<0)return false;buyer.money-=o.fee;c.players=c.players.filter(x=>x.id!==p.id);buyer.players.push(p);Bledger('מכירת '+fullName(p)+' ל'+buyer.name,o.fee);try{BpaperSale(p,buyer,o.fee)}catch(e){console.warn('paper',e)}c.lineup=(c.lineup||[]).map(id=>id===p.id?null:id);BensureXI(c);ensureCaptain(c);delete Bstate().saleOffer;try{Bcount('sales');BmsFill()}catch(e){}Bwrite();Btab='squad';Brender();Bdialog(`<h2>המכירה הושלמה</h2><p>${esc(fullName(p))} עבר ל${esc(buyer.name)} תמורת ${Bmoney(o.fee)}.</p>${Bbutton('בחזרה לסגל','data-bclose')}`);return true}

/* ====================== beginner career: leagues, contract, board, offers ======================
   Leagues the coach can work in (Bcat): Israel's four (top, Leumit, Liga Alef north and south) and the foreign leagues the
   data has real squads for. A club is addressed by a stable key (c.bkey): the id of an Israeli top club, 'eu<n>' (EURO_CLUBS),
   'l:<id>' (Leumit), 'a:<name>' (Liga Alef), 'w:<league>:<name>' (a market-league club). Only the clubs of a league somebody
   works in are built (BensureLeague), so the save stays small.
   The coach: b.coach, b.contract {years, wage (per month, for the story only), goal = worst acceptable place}, b.board 0..100.
   Results move the board; a board that lost its patience dismisses him (b.out), he may resign, and clubs make offers before a
   season (any league) and during it (same league only, so the table he joins is the one being played). */
function BcatBase(){if(BcatBase.c)return BcatBase.c;const base=Bdefs().map(d=>Object.assign({},d,{str:d.key.startsWith('eu')?EURO_CLUBS[+d.key.slice(2)][6]:(LSTR[d.key]||60)}));const il=base.filter(d=>d.country==='ישראל'),eu=base.filter(d=>d.country!=='ישראל');
  const W=(k,withCountry)=>{const L=WORLD_LEAGUES[k];const out=[];if(!L)return out;for(const c of L.clubs){const e=eu.find(x=>x.name===c[0]);if(e)out.push(e);else if(RAW_EURO[c[0]]&&RAW_EURO[c[0]].length>=14)out.push({key:'w:'+k+':'+c[0],name:c[0],country:c[6]||L.country,c1:c[2],c2:c[3],str:c[4],def:[c[0],c[6]||L.country,c[1],'',c[2],c[3],c[4]]})}
    if(withCountry)for(const e of eu)if(e.country===withCountry&&!out.includes(e))out.push(e);return out.sort((a,b)=>b.str-a.str)};
  const alef=lg=>(typeof RAW_ALEF!=='undefined'?RAW_ALEF:[]).filter(a=>a[4]===lg).map(a=>({key:'a:'+a[0],name:a[0],country:'ישראל',city:a[1],c1:a[2],c2:a[3],str:52}));
  const C=[{id:'il',name:'ישראל',leagues:[{id:'il1',name:'ליגת העל',tier:1,clubs:il},{id:'il2',name:'ליגה לאומית',tier:2,clubs:LEUMIT16.map(d=>({key:'l:'+d.id,name:d.name,country:'ישראל',c1:d.c1,c2:d.c2,str:d.str||55}))},{id:'il3n',name:'ליגה א׳ צפון',tier:3,clubs:alef('alef_north')},{id:'il3s',name:'ליגה א׳ דרום',tier:3,clubs:alef('alef_south')}]},
    {id:'en',name:'אנגליה',leagues:[{id:'en1',name:'פרמייר ליג',tier:1,clubs:W('epl','אנגליה')},{id:'en2',name:'צ׳מפיונשיפ',tier:2,clubs:W('champ')}]},
    {id:'es',name:'ספרד',leagues:[{id:'es1',name:'לה ליגה',tier:1,clubs:W('laliga','ספרד')},{id:'es2',name:'לה ליגה 2',tier:2,clubs:W('segunda')}]},
    {id:'it',name:'איטליה',leagues:[{id:'it1',name:'סרייה א׳',tier:1,clubs:W('seriea','איטליה')}]},
    {id:'de',name:'גרמניה',leagues:[{id:'de1',name:'בונדסליגה',tier:1,clubs:W('bundes','גרמניה')}]},
    {id:'fr',name:'צרפת',leagues:[{id:'fr1',name:'ליג 1',tier:1,clubs:W('ligue1','צרפת')}]},
    {id:'nl',name:'הולנד',leagues:[{id:'nl1',name:'ארדיוויזי',tier:1,clubs:W('eredivisie','הולנד')}]},
    {id:'pt',name:'פורטוגל',leagues:[{id:'pt1',name:'ליגת פורטוגל',tier:1,clubs:W('portugal','פורטוגל')}]},
    {id:'be',name:'בלגיה',leagues:[{id:'be1',name:'ליגת בלגיה',tier:1,clubs:W('belgium','בלגיה')}]}];
  for(const c of C)c.leagues=c.leagues.filter(l=>l.clubs.length>=6);BcatBase.c=C.filter(c=>c.leagues.length);
  /* the Champions League as a league of its own: the strongest clubs of the continent, at most four of one country. It stands
     last, so a club is always found in its own country's league first (BcatFind) */
  const per={},best=[];for(const {x,c} of BcatBase.c.flatMap(c=>c.leagues.filter(l=>l.tier===1).flatMap(l=>l.clubs.map(x=>({x,c})))).sort((a,b)=>b.x.str-a.x.str)){if(best.length>=BCL_N)break;if(best.includes(x)||(per[c.id]||0)>=4)continue;per[c.id]=(per[c.id]||0)+1;best.push(x)}
  if(best.length>=8)BcatBase.c.push({id:'cl',name:'אירופה',cup:true,leagues:[{id:'cl1',name:'ליגת האלופות',tier:0,cup:true,clubs:best}]});return BcatBase.c}
/* The catalogue as this career has it: BcatBase() is the world as it starts, b.moves {club key: league id} is what
   promotion and relegation changed since (moves.js). No career, or the opening of a new one (Bcat.raw): the base. */
function Bcat(){const base=BcatBase(),mv=!Bcat.raw&&G&&G.beginner&&G.beginner.moves;if(!mv||typeof mv!=='object')return base;let v=Bcat.w.get(mv);if(!v){v=BcatMoved(base,mv);Bcat.w.set(mv,v)}return v}
Bcat.w=new WeakMap();
const BCL_N=16;
const LSTR={mta:70,hta:69,mhf:69,hbs:70,bje:67,hhf:64,hje:63,mnt:64,mpt:61,bsk:61,hpt:61,hrg:59,iks:59,itb:59};
function BcatLeague(id){for(const c of Bcat())for(const l of c.leagues)if(l.id===id)return l;return null}
function BcatFind(key){for(const c of Bcat())for(const l of c.leagues){const x=l.clubs.find(x=>x.key===key);if(x)return {x,l,country:c}}return null}
function BclubByKey(key){return G.clubs.find(c=>c.bkey===key)||null}
/* what every club of a beginner career needs, whatever built it */
function BprepClub(c,key){if(key)c.bkey=key;c.div='top';c.pseudo=false;c.country=c.country||'ישראל';if(!c.realSquad)c.players.forEach(p=>p.real=false);c.youth=[];c.academy=0;c.sponsor=null;c.formation='4-3-3';c.ticket=80;if(c.fans==null)c.fans=50;c.baseDemand=Math.round(c.cap*(.48+c.fans/200));c.P=c.W=c.D=c.L=c.GF=c.GA=c.pts=0;autoLineupFor(c);return c}
function BaddClub(x){let c=BclubByKey(x.key);if(c)return c;
  if(x.key.startsWith('l:')){const d=LEUMIT16.find(d=>d.id===x.key.slice(2));if(!d)return null;c=buildLeumitClub(d)}
  else if(x.key.startsWith('a:'))c=buildLeumitClub({id:'ba'+(uid++),name:x.name,short:x.name.replace(/^(הפועל|מכבי|מ\.ס\.|מ\.כ\.|עירוני|בית"ר) /,''),city:x.city,stadium:'אצטדיון '+x.city,cap:3500,c1:x.c1,c2:x.c2,str:52});
  else if(x.def){c=clubFromDef(x.def,'b');delete G.pseudo[c.id];c.squadValue=c.players.reduce((s,p)=>s+Bvalue(p),0);c.money=Math.round(Math.max(8e6,c.squadValue*.3))}else return null;
  c.country=x.country;BprepClub(c,x.key);G.clubs.push(c);return c}
function BensureLeague(l){return l.clubs.map(x=>BaddClub(x)).filter(Boolean).map(c=>c.id)}
function BensureKeys(){for(const c of G.clubs){if(c.bkey)continue;if(META[c.id])c.bkey=c.id;else{const i=EURO_CLUBS.findIndex(d=>d[0]===c.name);if(i>=0)c.bkey='eu'+i}}const b=Bstate();if(!b.leagueId){const f=BcatFind(me().bkey);if(f&&f.l.clubs.every(x=>BclubByKey(x.key)&&b.league.includes(BclubByKey(x.key).id))&&b.league.length===f.l.clubs.length)b.leagueId=f.l.id}}
function BleagueName(){const l=BcatLeague(Bstate().leagueId);return l?l.name:'ליגת האימון'}
function Bplace(c=me()){return Bstandings().indexOf(c)+1}
/* where a side stands on the eve of a league match: its place and its points. Not before a ball was kicked (the order of a table of zeros
   is the alphabet's), and not in Europe, where the two clubs are in no table together. */
function BposHTML(x,cup){const b=Bstate();if(cup||!x||!b||b.round<1||!b.league.includes(x.id))return '';return `<small class="apos">מקום <bdi>${Bplace(x)}</bdi> · <bdi>${x.pts}</bdi> נק׳</small>`}
/* ---- contract and board ---- */
function BcontractFor(x,l){const n=l.clubs.length,above=l.clubs.filter(y=>y.str>x.str).length,ties=l.clubs.filter(y=>y.str===x.str).length,rank=Math.round(above+(ties+1)/2);   /* clubs of equal strength share the middle of their group */
  const z=BprZones(l),last=z.down?n-z.down:n-1,goal=clamp(rank+2,1,last);   /* where clubs go down, no board asks for less than staying up */
  return {years:2,wage:Math.round((9000+Math.pow(1.085,x.str-50)*7000)/500)*500,goal,rank,n,zone:z.down&&goal>=last?'stay':null}}
function BgoalText(k){return k.goal<=1?'לזכות באליפות':k.zone==='stay'?`להישאר בליגה: מקום <bdi>${k.goal}</bdi> או גבוה ממנו`:`לסיים במקום <bdi>${k.goal}</bdi> או גבוה ממנו`}
function BsignCoach(key,leagueId,opt){const f=BcatFind(key),l=BcatLeague(leagueId)||f.l,x=l.clubs.find(y=>y.key===key),b=Bstate();b.contract=Object.assign(BcontractFor(x,l),{since:b.season});b.board=55;b.offer=null;b.offerAt=null;b.out=null;b.verdict=null;b.jobs=b.jobs||[];b.jobs.push({season:b.season,club:x.name,league:l.name});if(opt&&opt.name!=null){b.coach=opt.name;if(G.manager)G.manager.name=opt.name}}
function BboardWord(v){return v>=75?'מרוצה מאוד':v>=55?'מרוצה':v>=35?'מודאגת':v>=20?'לוחצת':'על סף החלטה'}
/* after the coach's match: the result against what was expected of it, then the table against the goal */
function BboardAfter(M){const b=Bstate();if(!b.contract||b.out)return;const c=me(),home=M.h===c.id,gf=home?M.gh:M.ga,ga=home?M.ga:M.gh,opp=club(home?M.a:M.h),gap=strength(c)-strength(opp);
  let d=gf>ga?(gap<-4?6:4):gf===ga?(gap<-4?2:gap>4?-1:1):(gap<-4?-2:gap>4?-7:-5);if(b.round>=5){const pos=Bplace(c);d+=pos<=b.contract.goal?1:-(pos-b.contract.goal>3?2:1)}b.board=clamp((b.board==null?55:b.board)+d,0,100)}
/* ---- the job market ---- */
function BjobPool(lo,hi,sameLeague){const b=Bstate(),mine=me().bkey,out=[];for(const c of Bcat())for(const l of c.leagues){if(sameLeague?l.id!==b.leagueId:l.cup)continue;for(const x of l.clubs)if(x.key!==mine&&x.str>=lo&&x.str<=hi)out.push({key:x.key,league:l.id})}return out}
function BjobOffer(o){const f=BcatFind(o.key),l=BcatLeague(o.league),x=l.clubs.find(y=>y.key===o.key);return Object.assign({key:o.key,league:o.league,name:x.name,leagueName:l.name,c1:x.c1,c2:x.c2},BcontractFor(x,l))}
function BjobOffers(lo,hi,n,sameLeague){const pool=shuffle(BjobPool(lo,hi,sameLeague)),seen=new Set(),out=[];for(const o of pool){if(out.length>=n)break;if(seen.has(o.key))continue;seen.add(o.key);out.push(BjobOffer(o))}return out}
function BmyStr(){const f=BcatFind(me().bkey);return f?f.x.str:Math.round(strength(me()))}
/* The résumé, in strength points. A coach who has won things and lasted is wanted by better clubs than the one
   he just left; one who keeps being dismissed is wanted by worse. Without this, "another league" would be a
   list of every club in the world and the choice would mean nothing. */
function Bresume(){const b=Bstate(),jobs=b.jobs||[];
  let r=(b.honours||[]).length*4                                   /* a trophy is what a board reads first */
   +jobs.filter(j=>!j.end).length*2                                 /* a job he was not thrown out of */
   +Math.min(6,Math.max(0,(b.season||1)-1))                         /* seasons on the touchline */
   -jobs.filter(j=>j.end==='fired').length*3;
  if(b.board!=null)r+=Math.round((b.board-55)/12);                  /* how he is leaving, not only where from */
  return clamp(r,-8,14)}
/* The band of club strengths that will have him: where he is now, moved by the résumé. The ceiling never falls
   below his own level (minus a notch when he was dismissed) — a coach of the weakest league in the game would
   otherwise have a band under every club there is and nobody at all would answer him. */
function BjobBand(why){const s=BmyStr(),r=Bresume(),down=why==='fired'?16:12,up=why==='fired'?-3:1;
  return {lo:Math.max(0,s-down+Math.round(r/2)),hi:Math.max(s-(why==='fired'?4:0),s+up+r)}}
/* three clubs of one chosen league that want him. Nobody is invented to fill the list: a league whose clubs are
   all far above him answers with nothing, which is the point of showing the résumé at all. */
function BleagueOffers(leagueId,why,n){const b=Bstate(),band=BjobBand(why||(b.out&&b.out.why)||'resigned'),mine=me().bkey,l=BcatLeague(leagueId);
  if(!l)return [];
  /* Inside a league he chose himself there is no floor, only a ceiling: a club below his level will always have
     him, and he asked about this league. The best he can reach are drawn from, so the choice is between clubs
     worth having and not between the three weakest names on the list. */
  const fits=l.clubs.filter(x=>x.key!==mine&&x.str<=band.hi).sort((p,q)=>q.str-p.str).slice(0,Math.max(6,n||3));
  return shuffle(fits).slice(0,n||3).map(x=>BjobOffer({key:x.key,league:l.id}))}
/* out of work: clubs a step down always answer, so a career never ends on this screen */
function Bleave(why){const b=Bstate();Breturnloans();const s=BmyStr(),band=BjobBand(why);let offers=BjobOffers(band.lo,band.hi,3);if(offers.length<2)offers=BjobOffers(0,s+2,3);if(offers.length<2)offers=BjobOffers(0,200,3);
  try{BpaperDepart(why)}catch(e){console.warn('paper',e)}
  b.out={why,from:me().name,offers,first:offers,league:null,pick:false};b.offer=null;b.live=null;if(b.jobs&&b.jobs.length)b.jobs[b.jobs.length-1].end=why;Bwrite();Brender()}
function Breturnloans(){const b=Bstate();for(const l of b.loans||[]){const p=me().players.find(p=>p.id===l.pid),to=club(l.club);if(p&&to){me().players=me().players.filter(x=>x.id!==p.id);to.players.push(p)}}b.loans=[]}
/* take a job. In the league being played he joins its table as it stands; anywhere else a new season starts there. */
function BtakeJob(o){const was=me()&&me().name;const b=Bstate();let l=BcatLeague(o.league);const same=!b.out&&l.id===b.leagueId&&b.round<b.schedule.length;Breturnloans();b.build=null;
  if(!same&&(b.out||b.round>0)){try{BprApply()}catch(e){console.warn('moves',e)}if(!l.cup){const f=BcatFind(o.key);if(f&&!f.l.cup)l=f.l}}   /* the season turns: promotion and relegation first, and the club may have changed league since the offer was written */
  const ids=BensureLeague(l),c=BclubByKey(o.key);if(!c)return;
  G.me=c.id;c.sponsor=null;BensureXI(c);c.money=Math.max(c.money,Math.round(Bsum()*.7));if(same&&b.cl){b.cl.out=!b.cl.alive.includes(G.me);b.cl.won=b.cl.champion===G.me}
  if(!same){if(b.out||b.round>0){b.season++;G.season=b.season}b.league=ids;b.leagueId=l.id;Bseason()}
  BsignCoach(o.key,l.id);b.opening=c.money;b.sponsorOffers=pickSponsorBrands(c,3).map(x=>({id:x.id,annual:Math.round(Math.max(Bsum()*.4,300000)),years:1}));Btab='home';Bnotice='חתמת ב'+c.name;try{BpaperAppoint(was)}catch(e){console.warn('paper',e)}try{b.tip=null;b.vs={};b.st={w:0};b.bid=null;b.bidNo={};b.bidAt=null;BmsFill()}catch(e){console.warn('engage',e)}Bwrite();Brender()}
/* after every round: dismissal, and now and then an offer from a bigger club of the same league */
function BcareerRound(){const b=Bstate();if(!b.contract||b.out)return null;const n=b.schedule.length,left=n-b.round;
  if(b.offer&&b.round>=b.offer.until)b.offer=null;
  if(b.round>=Math.max(8,Math.round(n*.35))&&left>=2&&b.board<=12)return 'fired';
  if(!b.offer&&left>=4&&b.round>=5&&b.board>=68&&Bplace()<=b.contract.goal&&(b.round===Math.round(n/2)||Math.random()<.14)&&b.offerAt!==b.season+':'+Math.floor(b.round/6)){const s=BmyStr(),o=BjobOffers(s+1,s+12,1,true)[0];if(o){b.offer=Object.assign(o,{until:b.round+2});b.offerAt=b.season+':'+Math.floor(b.round/6);try{BpaperOffer(b.offer)}catch(e){console.warn('paper',e)}}}
  return null}
/* the end of a season: did he meet the goal, does the contract go on, who calls */
function BseasonVerdict(){const b=Bstate(),k=b.contract;if(!k)return {stay:true,offers:[],text:''};const pos=Bplace(),met=pos<=k.goal,s=BmyStr();if(b.verdict&&b.verdict.season===b.season)return b.verdict;
  const yearsLeft=k.years-(b.season-k.since+1);let stay=true,text;
  if(!met&&(pos-k.goal>=3||b.board<30)){stay=false;text=`סיימת במקום <bdi>${pos}</bdi>, והיעד היה ${BgoalText(k)}. ההנהלה החליטה להיפרד.`}
  else if(yearsLeft<=0&&b.board<40){stay=false;text=`החוזה הסתיים וההנהלה בחרה לא לחדש אותו.`}
  else text=met?`עמדת ביעד: מקום <bdi>${pos}</bdi>. ${yearsLeft<=0?'ההנהלה מציעה חוזה חדש.':'החוזה ממשיך.'}`:`סיימת במקום <bdi>${pos}</bdi>, מעט מתחת ליעד. ההנהלה נותנת עונה נוספת.`;
  const up=met?clamp(Math.round((k.goal-pos)*1.5)+Math.round((b.board-55)/8),0,12):0;const offers=stay?BjobOffers(s-4,s+2+up,2):[];
  b.verdict={season:b.season,stay,text,offers,met,pos,renew:stay&&yearsLeft<=0};return b.verdict}
function BstayOn(){const b=Bstate(),v=b.verdict;if(v&&v.renew){const f=BcatFind(me().bkey),l=BcatLeague(b.leagueId)||(f&&f.l);if(f&&l)b.contract=Object.assign(BcontractFor(f.x,l),{since:b.season+1})}b.board=clamp(Math.round(((b.board==null?55:b.board)+55)/2),30,80);b.verdict=null}
/* ---- the Champions League inside a career ----
   A coach of a country's top division whose club qualified (the head of last season's table; in a first season the
   strongest clubs of the league) plays it beside the league: sixteen clubs, one match a round, four evenings spread
   over the season. A level match goes to penalties. b.cl = {season, ids, alive, stage, at, ties, res, out, won}. */
const BCL_STAGES=['שמינית הגמר','רבע הגמר','חצי הגמר','הגמר'],BCL_PRIZE=[1200000,2000000,3500000,7000000];
function BclPlaces(l){return Math.max(2,Math.round(l.clubs.length/5))}
function BclQualified(l){const b=Bstate(),q=b.clq;return q&&q.league===l.id&&q.season===b.season-1?q.keys:l.clubs.slice().sort((x,y)=>y.str-x.str).slice(0,BclPlaces(l)).map(x=>x.key)}
function BclPairs(ids){const s=shuffle(ids.slice()),out=[];for(let i=0;i<s.length;i+=2)out.push([s[i],s[i+1]]);return out}
function BclDraw(){const b=Bstate(),l=BcatLeague(b.leagueId);b.cl=null;if(!l||l.tier!==1||l.cup)return;const mine=BclQualified(l);if(!mine.includes(me().bkey))return;
  const per={},field=l.clubs.filter(x=>mine.includes(x.key)),home=Bcat().find(c=>c.leagues.includes(l));
  for(const {x,c} of Bcat().filter(c=>!c.cup&&c!==home).flatMap(c=>c.leagues.filter(y=>y.tier===1).flatMap(y=>y.clubs.map(x=>({x,c})))).sort((a,z)=>z.x.str-a.x.str)){if(field.length>=16)break;if((per[c.id]||0)>=4)continue;per[c.id]=(per[c.id]||0)+1;field.push(x)}
  const ids=field.map(x=>BaddClub(x)).filter(Boolean).map(c=>c.id);if(ids.length!==16||!ids.includes(G.me))return;const n=b.schedule.length;
  b.cl={season:b.season,ids,alive:ids.slice(),stage:0,at:[.18,.42,.66,.88].map(f=>Math.max(1,Math.min(n-1,Math.round(n*f)))),ties:BclPairs(ids),res:[],out:false,won:false}}
/* the coach's tie, when its evening has come */
function BclTie(){const k=Bstate().cl;if(!k||k.out||k.stage>3||Bstate().round<k.at[k.stage])return null;return k.ties.find(t=>t.includes(G.me))||null}
function BclSim(h,a,final){const M=createMatch(club(h),club(a),{kind:'friendly',neutral:!!final});while(!M.done)stepMinute(M);if(M.gh===M.ga)decidePens(M);return M}
/* close a stage: the coach's match (when he played one) and every other tie, then the draw of the next stage */
function BclClose(mine){const b=Bstate(),k=b.cl,st=k.stage,row=[],next=[];for(const [h,a] of k.ties){const M=mine&&mine.h===h&&mine.a===a?mine:BclSim(h,a,st===3);const w=M.gh>M.ga||(M.gh===M.ga&&M.pens==='h')?h:a;row.push({h,a,gh:M.gh,ga:M.ga,pens:M.gh===M.ga?(M.penScore||true):null,w});next.push(w)}
  k.res.push(row);k.alive=next;k.stage=st+1;if(!next.includes(G.me))k.out=true;if(st===3){k.champion=next[0];k.won=next[0]===G.me;k.ties=[]}else k.ties=BclPairs(next)}
/* evenings the coach has no part in any more are played without him, so the season always gets its champion */
function BclNight(){const b=Bstate(),k=b.cl;if(!k)return;while(k.stage<=3&&b.round>=k.at[k.stage]&&(k.out||!k.ties.some(t=>t.includes(G.me))))BclClose(null)}
function BclFinish(M){const b=Bstate(),k=b.cl,st=k.stage,c=me(),home=M.h===G.me,final=st===3;document.querySelector('.bdialog')?.remove();
  if(home&&!final){const crowd=Math.min(c.cap,Math.round((c.baseDemand||c.cap*.75)*1.25));Bledger('הכנסה מכרטיסים · ליגת האלופות · '+crowd.toLocaleString('he')+' אוהדים',crowd*110)}
  BclClose(M);BmoraleAfter(M);const won=!k.out;try{BpaperCL(M,st,won,final)}catch(e){console.warn('paper',e)}if(won){Bledger(final?'פרס הזכייה בליגת האלופות':'פרס ליגת האלופות · עלייה ל'+BCL_STAGES[st+1],BCL_PRIZE[st]);b.board=clamp((b.board==null?55:b.board)+(final?15:4),0,100);if(final)(b.honours=b.honours||[]).push({season:b.season,what:'ליגת האלופות',club:c.name})}
  BclNight();Btab='home';let gain=null;try{gain=BxpMatch(M)}catch(e){console.warn('engage',e)}Bwrite();Brender();const pens=M.gh===M.ga?`<p class="bcl-pens">${won?'ניצחון':'הפסד'} בפנדלים${M.penScore?` <bdi>${M.penScore[home?0:1]}:${M.penScore[home?1:0]}</bdi>`:''}</p>`:'';
  const show=()=>Bdialog(`<div class="bresult"><span class="beyebrow">ליגת האלופות · ${BCL_STAGES[st]}</span><h2 class="bresult-board"><span>${kitSVG(club(M.h),'lg')}<strong>${esc(club(M.h).name)}</strong></span>${scoreSides(M.gh,M.ga,{label:club(M.h).name+' '+M.gh+', '+club(M.a).name+' '+M.ga})}<span>${kitSVG(club(M.a),'lg')}<strong>${esc(club(M.a).name)}</strong></span></h2>${pens}<p class="bcl-verdict">${final&&won?'אלופי אירופה! הגביע עם האוזניים הגדולות שלכם.':won?'עליתם ל'+BCL_STAGES[st+1]+'. הפרס נכנס לקופת המועדון.':'המסע באירופה הסתיים העונה. הליגה ממשיכה.'}</p>${BxpStripHTML(gain)}${BmatchFactsHTML(M)}${BratingsHTML(M)}<div class="bresult-foot">${BresultFoot()}</div></div>`);
  /* the cup with the big ears is lifted before anybody reads a score */
  if(final&&won&&typeof openMoment==='function'){try{openMoment({id:'b-cl-'+b.season,kind:'cup',comp:'ליגת האלופות',club:G.me,clubName:c.name,season:npSeasonOf({s:b.season}),shown:true},{onClose:show});if(document.getElementById('reveal'))return}catch(e){console.warn('moment',e);try{closeReveal(true)}catch(x){}}}show()}
function BclTieHTML(r){const h=club(r.h),a=club(r.a);if(!h||!a)return '';return `<li class="${r.h===G.me||r.a===G.me?'mine':''}"><span class="${r.w===r.h?'w':''}">${esc(h.name)}</span>${r.gh==null?'<em>–</em>':scoreSides(r.gh,r.ga,{label:h.name+' '+r.gh+', '+a.name+' '+r.ga})}<span class="${r.w===r.a?'w':''}">${esc(a.name)}</span>${r.pens?`<small>${esc(club(r.w).name)} בפנדלים</small>`:''}</li>`}
/* the home card: the evening that waits, or how far it went */
function BclCard(){const b=Bstate(),k=b.cl;if(!k)return '';const t=k.ties.find(x=>x.includes(G.me)),due=BclTie(),last=k.res.length?k.res[k.res.length-1].find(r=>r.h===G.me||r.a===G.me):null;
  const lost=k.res.findIndex(row=>row.some(r=>(r.h===G.me||r.a===G.me)&&r.w!==G.me)),where=lost<0?'המועדון לא משתתף העונה.':`הודחתם ב${BCL_STAGES[lost]}.`;
  const line=k.won?'זכיתם בגביע. אלופי אירופה!':k.out?where+(k.champion?` האלופה: ${esc(club(k.champion).name)}.`:' הטורניר ממשיך בלעדיכם.'):t?`${due?BCL_STAGES[k.stage]+': ':''}${esc(club(t[0]).name)} מול ${esc(club(t[1]).name)}${due?'':` · אחרי מחזור <bdi>${k.at[k.stage]}</bdi>`}`:'';
  return `<section class="bpanel bcl"><div class="bcl-head"><span class="bstar" aria-hidden="true">★</span><div><span class="beyebrow">ליגת האלופות</span><h2>${k.won?'הגביע שלכם':k.out?'המסע הסתיים':due?'ערב אירופי':BCL_STAGES[k.stage]}</h2><p>${line}</p></div></div>${last?`<ul class="bcl-ties">${BclTieHTML(last)}</ul>`:''}</section>`}
function BclLeagueHTML(){const k=Bstate().cl;if(!k)return '';const rounds=k.res.map((row,i)=>[BCL_STAGES[i],row]);if(k.stage<=3&&k.ties.length)rounds.push([BCL_STAGES[k.stage],k.ties.map(([h,a])=>({h,a}))]);
  return `<section class="bpanel bcl"><h2>ליגת האלופות</h2>${rounds.slice().reverse().map(([n,row])=>`<h3>${n}</h3><ul class="bcl-ties">${row.map(BclTieHTML).join('')}</ul>`).join('')}</section>`}
/* ---- screens ---- */
function BofferHTML(o,attr,cta){return `<article class="boffer">${kitSVG(o,'lg')}<div><strong>${esc(o.name)}</strong><small>${esc(o.leagueName)} · חוזה ל־<bdi>${o.years}</bdi> עונות · ${Bmoney(o.wage)} לחודש</small><small>היעד: ${BgoalText(o)}</small></div>${Bbutton(cta||'לחתום',`${attr}="${esc(o.key)}"`,'secondary')}</article>`}
function BcareerPanel(){const b=Bstate(),k=b.contract;if(!k)return '';const until=k.since+k.years-1,v=b.board==null?55:b.board;
  return `<section class="bpanel bcareer"><div class="bcareer-head"><div><span class="beyebrow">המאמן</span><h2>${esc(b.coach||'המאמן')}</h2><p>${esc(BleagueName())} · חוזה עד סוף עונה <bdi>${until}</bdi> · היעד: ${BgoalText(k)}</p></div><button type="button" class="blink" data-action="resign">להתפטר</button></div>
  <div class="bboard" role="img" aria-label="אמון ההנהלה ${v} מתוך 100"><span>אמון ההנהלה</span><div class="bboard-bar"><i style="width:${v}%" class="${v>=55?'good':v>=30?'mid':'low'}"></i></div><strong>${BboardWord(v)}</strong></div>
  ${BcareerStatsHTML()}
  ${b.offer?`<div class="boffers"><h3>הצעה על השולחן (עד מחזור <bdi>${b.offer.until}</bdi>)</h3>${BofferHTML(b.offer,'data-bjob','לעבור עכשיו')}<button type="button" class="blink" data-action="decline">לדחות את ההצעה</button></div>`:''}</section>`}
function BoutHTML(){const o=Bstate().out,wrap=inner=>`<div class="bapp"><header class="btop"><a class="bbrand" href="beginner.html">GOALASSO<span>START</span></a><span class="bpill">מצב מתחילים</span></header><section class="bpanel bout">${inner}</section></div>`;
  if(o.pick)return wrap(`${Bheader('תחנה הבאה','באיזו ליגה',`הקורות שלך פתוחים בפני המועדונים האלה. ליגה חזקה מדי לא תענה — ${BresumeText()}`)}<div class="bout-leagues">${Bcat().map(c=>{const ls=c.leagues.filter(l=>!l.cup);if(!ls.length)return '';
    return `<div class="bout-country"><h3>${esc(c.name)}</h3>${ls.map(l=>{const n=BleagueReach(l);
     /* a league where nothing is within reach says so instead of answering with an empty screen: that is the
        résumé made visible, and it opens by itself as the career grows */
     return n?Bbutton(esc(l.name),`data-boutleague="${esc(l.id)}"`,'secondary'):`<button type="button" class="bbtn secondary off" disabled>${esc(l.name)}<small>מעליך</small></button>`}).join('')}</div>`}).join('')}</div><button type="button" class="blink" data-action="bout-back">חזרה להצעות</button>`);
  const l=o.league&&BcatLeague(o.league);
  const head=l?Bheader('תחנה הבאה',esc(l.name),o.offers.length?'המועדונים בליגה הזאת שרוצים אותך עכשיו.':'אף מועדון בליגה הזאת לא רוצה אותך בשלב הזה של הקריירה. בחר ליגה אחרת.')
   :Bheader(o.why==='fired'?'פיטורים':'התפטרות',o.why==='fired'?`${esc(o.from)} נפרדה ממך`:`עזבת את ${esc(o.from)}`,o.why==='fired'?'התוצאות לא הספיקו להנהלה. מאמנים טובים חוזרים מזה: בחר את התחנה הבאה.':'מי שמחפש אתגר חדש מוצא אותו. אלה המועדונים שרוצים אותך עכשיו.');
  return wrap(`${head}<div class="boffers">${o.offers.map(x=>BofferHTML(x,'data-bjob')).join('')}</div>
   ${Bbutton('ליגה אחרת','data-action="bout-leagues"','secondary')}
   <p class="bmuted">עונה חדשה תתחיל במועדון שתבחר. הסגל, הכסף והטבלה הם של המועדון החדש.</p>`)}
/* how many clubs of a league would have him at all */
function BleagueReach(l){const b=Bstate(),band=BjobBand((b.out&&b.out.why)||'resigned'),mine=me().bkey;
  return l&&!l.cup?l.clubs.filter(x=>x.key!==mine&&x.str<=band.hi).length:0}
function BresumeText(){const r=Bresume();return r>=8?'הקורות שלך פותחים דלתות גבוהות.':r>=3?'יש לך מוניטין סביר.':r>=-2?'אתה בתחילת הדרך.':'אחרי מה שהיה, תצטרך להוכיח את עצמך מחדש.'}
/* the opening: name, league, club; the contract is signed in a dialog */
/* flags, drawn (emoji flags are missing on some systems and England has none of its own) */
function Bflag(id){const R=(x,y,w,h,f)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${f}"/>`,V=(a,b,c)=>R(0,0,12,24,a)+R(12,0,12,24,b)+R(24,0,12,24,c),H=(a,b,c)=>R(0,0,36,8,a)+R(0,8,36,8,b)+R(0,16,36,8,c);
  const F={il:R(0,0,36,24,'#fff')+R(0,3,36,3.4,'#0038b8')+R(0,17.6,36,3.4,'#0038b8')+'<path d="M18 7.6l3.5 6h-7zM18 16.4l-3.5-6h7z" fill="none" stroke="#0038b8" stroke-width="1.1"/>',
    en:R(0,0,36,24,'#fff')+R(15,0,6,24,'#ce1124')+R(0,9,36,6,'#ce1124'),es:R(0,0,36,24,'#aa151b')+R(0,6,36,12,'#f1bf00'),it:V('#009246','#fff','#ce2b37'),de:H('#111','#dd0000','#ffce00'),fr:V('#0055a4','#fff','#ef4135'),
    nl:H('#ae1c28','#fff','#21468b'),pt:R(0,0,14.4,24,'#046a38')+R(14.4,0,21.6,24,'#da291c')+'<circle cx="14.4" cy="12" r="4.4" fill="#ffe900" stroke="#fff" stroke-width=".6"/>',be:V('#111','#fae042','#ed2939')};
  return `<svg class="bflag" viewBox="0 0 36 24" aria-hidden="true">${F[id]||R(0,0,36,24,'#33475b')}</svg>`}
/* the opening: the name (also asked on the title screen), then the league and the club in front of the stadium */
function BstartHTML(){const s=Bstart,cat=Bcat();const back=(to,t)=>`<button type="button" class="blink" data-bstep="${to}">${t||'חזרה'}</button>`;
  if(s.step==='league'){
    return `<section class="bpick" id="bstart"><h1>${esc(s.name)}, איפה תאמן?</h1><p class="bpick-sub">בחר מדינה וליגה. את המועדון תבחר מיד אחר כך.</p>
    <div class="bcountries">${cat.filter(c=>!c.cup).map(c=>`<div class="bcountry${s.country===c.id?' open':''}"><button type="button" data-bcountry="${c.id}" aria-expanded="${s.country===c.id}">${Bflag(c.id)}<strong>${esc(c.name)}</strong><small>${c.leagues.length>1?`<bdi>${c.leagues.length}</bdi> ליגות`:esc(c.leagues[0].name)}</small></button>${s.country===c.id&&c.leagues.length>1?`<div class="bleagues">${c.leagues.map(l=>`<button type="button" data-bleague="${l.id}"><strong>${esc(l.name)}</strong><small><bdi>${l.clubs.length}</bdi> מועדונים</small></button>`).join('')}</div>`:''}</div>`).join('')}</div>
    <div class="bmodes">${BcatLeague('cl1')?`<button type="button" class="bmode" data-bleague="cl1"><span class="bmode-ic" aria-hidden="true">★</span><strong>ליגת האלופות</strong><small><bdi>${BcatLeague('cl1').clubs.length}</bdi> המועדונים החזקים באירופה, כולם נגד כולם</small></button>`:''}</div>
    <div class="bfilters"><label>או חפש מועדון בשם<input id="bclubsearch" value="${esc(s.q||'')}" placeholder="למשל ליברפול או מכבי חיפה" autocomplete="off"></label></div><div id="bclubhits">${BclubHitsHTML()}</div>${back('name','שינוי שם')}</section>`}
  if(s.step==='club'){const l=BcatLeague(s.league),c=cat.find(c=>c.leagues.includes(l));return `<section class="bpick" id="bstart"><h1>${l.cup?'<span class="bstar" aria-hidden="true">★</span>':Bflag(c?c.id:'')} ${esc(l.name)}</h1><p class="bpick-sub">${l.cup?'הגדולים של אירופה בליגה אחת, בית וחוץ. כאן אין יריבה קלה. ':''}איזה מועדון תוביל? מועדון חזק נותן סגל טוב יותר, וגם יעד קשה יותר בחוזה.</p><div class="bclubgrid">${l.clubs.map(x=>`<button class="bclub" data-bpick="${esc(x.key)}" data-bpl="${l.id}">${kitSVG(x,'lg')}<strong>${esc(x.name)}</strong><span>${l.cup?esc(x.country||'')+' · ':''}חוזק <bdi>${Math.round(x.str)}</bdi></span></button>`).join('')}</div>${back('league','חזרה לליגות')}</section>`}
  return `<section class="bpanel bstart" id="bstart"><h2>איך קוראים לך, מאמן?</h2><form data-bnameform><label class="bfield">השם שיופיע על החוזה<input id="bcoach" maxlength="24" autocomplete="name" value="${esc(s.name)}" placeholder="למשל אבי לוי"></label><p class="bstart-err" role="alert">${esc(s.err||'')}</p>${Bbutton('ממשיכים לבחירת ליגה','type="submit"')}</form></section>`}
/* the clubs a typed name finds: drawn alone, so the field keeps its keyboard while he types */
function BclubHitsHTML(){const q=(Bstart.q||'').trim(),hits=q.length>=2?Bcat().filter(c=>!c.cup).flatMap(c=>c.leagues.flatMap(l=>l.clubs.filter(x=>x.name.includes(q)).map(x=>({x,l})))).slice(0,12):[];
  return hits.length?`<div class="bclubgrid">${hits.map(({x,l})=>`<button class="bclub" data-bpick="${esc(x.key)}" data-bpl="${l.id}">${kitSVG(x,'lg')}<strong>${esc(x.name)}</strong><span>${esc(l.name)}</span></button>`).join('')}</div>`:q.length>=2?'<p class="bmuted">לא נמצא מועדון בשם הזה.</p>':''}
function BcontractDialog(key,leagueId){const f=BcatFind(key),l=BcatLeague(leagueId)||f.l,x=l.clubs.find(y=>y.key===key),k=BcontractFor(x,l);Bstart.club=key;Bstart.league=l.id;
  Bdialog(`<div class="bcontract"><span class="beyebrow">חוזה מאמן</span><h2>${kitSVG(x,'lg')} ${esc(x.name)}</h2><dl><dt>המאמן</dt><dd>${esc(Bstart.name)}</dd><dt>הליגה</dt><dd>${esc(l.name)}</dd><dt>תקופה</dt><dd><bdi>${k.years}</bdi> עונות</dd><dt>שכר</dt><dd>${Bmoney(k.wage)} לחודש</dd><dt>היעד של ההנהלה</dt><dd>${BgoalText(k)}</dd></dl><p class="blearn">ההנהלה עוקבת אחרי התוצאות. מי שעומד ביעד מקבל הצעות ממועדונים גדולים יותר; מי שרחוק ממנו עלול להיות מפוטר.</p>${Bbutton('חותם על החוזה','data-bsign')}<button type="button" class="blink" data-bclose>בוחר מועדון אחר</button></div>`)}
/* the title screen's button: a new coach must have written a name; true = the title screen may close */
function BsplashGo(){if(G?.beginner)return true;const el=document.getElementById('spName');if(!el)return true;const v=el.value.trim();if(v.length<2){el.setAttribute('aria-invalid','true');const er=document.getElementById('spErr');if(er)er.textContent='כתוב שם של שתי אותיות לפחות.';el.focus();return false}
  Bstart.name=v;Bstart.err='';Bstart.step='league';Brender();setTimeout(()=>document.getElementById('bstart')?.scrollIntoView?.({block:'start'}),480);return true}
/* clicks of the opening steps (no career yet); true = handled */
function BstartClick(el){const d=el.dataset;if(d.bstep){Bstart.step=d.bstep;Brender();$('bstart')?.scrollIntoView?.({block:'start'});return true}
  if(d.bcountry){const c=Bcat().find(x=>x.id===d.bcountry);if(!c)return true;if(c.leagues.length===1){Bstart.country=c.id;Bstart.league=c.leagues[0].id;Bstart.step='club'}else Bstart.country=Bstart.country===c.id?null:c.id;Brender();$('bstart')?.scrollIntoView?.({block:'start'});return true}
  if(d.bleague){Bstart.league=d.bleague;Bstart.step='club';Brender();$('bstart')?.scrollIntoView?.({block:'start'});return true}
  if(d.bpick){if(G?.beginner)return true;BcontractDialog(d.bpick,d.bpl);return true}
  if(el.hasAttribute('data-bsign')){if(G?.beginner||!Bstart.club)return true;el.closest('dialog')?.remove();const s=Bstart;Bcreate(s.club,{name:s.name,league:s.league});Bstart={step:'name',name:'',country:null,league:null,club:null,q:'',err:''};window.scrollTo?.(0,0);return true}
  return false}
document.addEventListener('submit',e=>{if(!e.target.matches||!e.target.matches('[data-bnameform]'))return;e.preventDefault();const v=(document.getElementById('bcoach')?.value||'').trim();if(v.length<2){Bstart.err='כתוב שם של שתי אותיות לפחות.';Brender();document.getElementById('bcoach')?.focus();return}Bstart.name=v;Bstart.err='';Bstart.step='league';Brender();$('bstart')?.scrollIntoView?.({block:'start'})});
